package com.bank.auth;

import java.io.*;
import java.util.Arrays;

public class LoginCredentials implements Serializable {
    private static final long serialVersionUID = 1L;

    private String accountId;              // persisted normally
    private String username;               // persisted normally

    // SECURITY: password as a transient char[] — excluded from serialization,
    // and clearable from memory (unlike an interned String).
    private transient char[] password;

    public LoginCredentials(String accountId, String username, char[] password) {
        this.accountId = accountId;
        this.username = username;
        this.password = password;
    }

    // Defense in depth: assert no secret is being written (password is transient anyway).
    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject(); // writes only non-transient fields (password skipped)
    }

    // On load, password stays null — must re-authenticate, never recovered from storage.
    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        this.password = null; // explicit: credential not restored from the stream
    }

    public String getAccountId() { return accountId; }
    public String getUsername() { return username; }
    public char[] getPassword() { return password; }

    // Clear the secret from memory when done with it.
    public void clearPassword() {
        if (password != null) { Arrays.fill(password, '\0'); password = null; }
    }
}
