package com.bank.auth;

import java.io.*;
import java.util.logging.*;

public class PasswordTransientDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        char[] secret = "SuperSecret123".toCharArray();
        LoginCredentials rajesh = new LoginCredentials("SAV2001", "rajesh.kumar", secret);
        log.info(() -> "BEFORE serialize: username=" + rajesh.getUsername()
                        + " password present=" + (rajesh.getPassword() != null));

        // Serialize to bytes (simulating a session cache write)
        byte[] bytes;
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(rajesh);
            bytes = baos.toByteArray();
        }

        // Prove the secret does NOT appear anywhere in the serialized bytes
        String asText = new String(bytes, java.nio.charset.StandardCharsets.ISO_8859_1);
        boolean leaked = asText.contains("SuperSecret123");
        log.info(() -> "Serialized " + bytes.length + " bytes");
        if (leaked) log.severe("PASSWORD LEAKED into serialized bytes!");
        else log.info("Password NOT found in serialized bytes (transient excluded it) — SECURE.");

        // Deserialize — password must be null
        LoginCredentials restored;
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            restored = (LoginCredentials) ois.readObject();
        }
        log.info(() -> "AFTER deserialize: accountId=" + restored.getAccountId()
                        + " username=" + restored.getUsername());
        log.warning(() -> "AFTER deserialize: password present=" + (restored.getPassword() != null)
                           + " (null → must re-authenticate)");

        // Clear the in-memory secret when done
        rajesh.clearPassword();
        log.info("Original in-memory password cleared.");
    }
}
